def transform(grid):
    """Trace the color-2 stream: move inward from its edge, then follow 8-wall faces to their gaps."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sources = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not sources:
        return out
    r, c = sources[0]
    # The source points inward from the edge on which it lies.
    if r == 0:
        dr, dc = 1, 0
    elif r == h - 1:
        dr, dc = -1, 0
    elif c == 0:
        dr, dc = 0, 1
    elif c == w - 1:
        dr, dc = 0, -1
    else:
        return out

    pending = deque([(r, c, dr, dc)])
    visited = set()
    while pending:
        r, c, dr, dc = pending.popleft()
        state = (r, c, dr, dc)
        if state in visited:
            continue
        visited.add(state)
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] != 8:
                out[rr][cc] = 2
                rr += dr
                cc += dc
                continue

            # Follow the contiguous 8 segment perpendicular to the stream.
            if dr:
