                while lo > 0 and grid[rr][lo - 1] == 8:
                    lo -= 1
                while hi + 1 < w and grid[rr][hi + 1] == 8:
                    hi += 1
                side_r = rr - dr
                for x in range(lo, hi + 1):
                    if grid[side_r][x] != 8:
