                lo = hi = rr
                while lo > 0 and grid[lo - 1][cc] == 8:
                    lo -= 1
                while hi + 1 < h and grid[hi + 1][cc] == 8:
                    hi += 1
                side_c = cc - dc
                for y in range(lo, hi + 1):
                    if grid[y][side_c] != 8:
                        out[y][side_c] = 2
                openings = [(lo - 1, cc), (hi + 1, cc)]

